import { MediaFormatInspector } from './format-inspector';
import { AvcFragmentMuxer, Mp4SampleStream } from './mp4-sample-stream';
import { BoundedVideoTranscoder } from './bounded-video-transcoder';
import { cancellable, MEDIA_LIMITS, type BoundedMediaSource, type MediaEnvironment } from './types';
import { linkAbort } from './adapters/range-source';

type Inspection = Awaited<ReturnType<MediaFormatInspector['openMp4']>>;
export interface Mp4PlaybackOptions {
  signal?: AbortSignal;
  encoderConfig?: VideoEncoderConfig;
  decoderConfig?: VideoDecoderConfig;
  startTime?: number;
  autoplay?: boolean;
  onError?: (error: unknown) => void;
  onMetrics?: Parameters<BoundedVideoTranscoder['run']>[0]['onMetrics'];
}

function event(target: EventTarget, name: string, signal: AbortSignal) {
  return new Promise<void>((resolve, reject) => {
    const cleanup = () => { clearTimeout(timer); target.removeEventListener(name, done); target.removeEventListener('error', error); signal.removeEventListener('abort', abort); };
    const done = () => { cleanup(); resolve(); };
    const error = () => { cleanup(); reject(new Error(`Media ${name} failed`)); };
    const abort = () => { cleanup(); reject(signal.reason); };
    const timer = setTimeout(error, MEDIA_LIMITS.operationTimeoutMs);
    target.addEventListener(name, done, { once: true }); target.addEventListener('error', error, { once: true });
    signal.addEventListener('abort', abort, { once: true }); if (signal.aborted) abort();
  });
}

/** A streaming MediaSource URL, never a whole-file Blob. One epoch owns each seek. */
export class Mp4StreamPlayback {
  private lifetime = new AbortController();
  private run?: AbortController;
  private pumping: Promise<void> = Promise.resolve();
  private switching = Promise.resolve();
  private samples: Mp4SampleStream;
  private url = '';
  private media?: MediaSource;
  private runStart = 0;
  private restarting = false;
  private revision = 0;
  metrics?: Awaited<ReturnType<BoundedVideoTranscoder['run']>>;
  private constructor(private source: BoundedMediaSource, private inspection: Inspection,
    private video: HTMLVideoElement, private options: Mp4PlaybackOptions, private env: MediaEnvironment) {
    this.samples = new Mp4SampleStream(source, inspection);
  }
  static async open(source: BoundedMediaSource, inspection: Inspection, video: HTMLVideoElement,
    options: Mp4PlaybackOptions = {}, env: MediaEnvironment = globalThis) {
    const session = new Mp4StreamPlayback(source, inspection, video, options, env);
    const abort = () => { void session.close(); };
    options.signal?.addEventListener('abort', abort, { once: true });
    session.lifetime.signal.addEventListener('abort', () => options.signal?.removeEventListener('abort', abort), { once: true });
    if (options.signal?.aborted) { await session.close(); options.signal.throwIfAborted(); }
    video.addEventListener('seeking', session.onSeeking);
    try { await session.seek(options.startTime || 0, options.autoplay ?? (!video.paused || video.autoplay)); return session; }
    catch (error) { await session.close(); throw error; }
  }
  private onSeeking = () => {
    if (this.restarting || this.lifetime.signal.aborted || Math.abs(this.video.currentTime - this.runStart) < .05) return;
    for (let i = 0; i < this.video.buffered.length; i++)
      if (this.video.currentTime >= this.video.buffered.start(i) && this.video.currentTime < this.video.buffered.end(i)) return;
    void this.seek(this.video.currentTime).catch(error => { if (!this.lifetime.signal.aborted) this.options.onError?.(error); });
  };
  get done() { return this.pumping; }
  seek(time: number, playing = !this.video.paused) {
    if (!Number.isFinite(time) || time < 0) return Promise.reject(new Error('Invalid media seek'));
    const continuity = { rate: this.video.playbackRate, volume: this.video.volume, muted: this.video.muted, loop: this.video.loop };
    const revision = ++this.revision;
    this.run?.abort();
    const restart = this.switching.catch(() => {}).then(() => this.start(time, playing, continuity, revision));
    this.switching = restart;
    return restart;
  }
  private async start(time: number, playing: boolean, continuity: { rate: number; volume: number; muted: boolean; loop: boolean }, revision: number) {
    this.lifetime.signal.throwIfAborted();
    if (revision !== this.revision) return;
    await this.pumping.catch(() => {});
    this.lifetime.signal.throwIfAborted();
    if (revision !== this.revision) return;
    this.releaseMedia();
    const link = linkAbort(this.lifetime.signal), signal = link.controller.signal;
    this.run = link.controller; this.runStart = time; this.restarting = true;
    const Source = this.env.ManagedMediaSource || this.env.MediaSource;
    if (!Source) { link.dispose(); throw new Error('MSE unavailable'); }
    const media: MediaSource = this.media = new Source();
    this.url = this.env.URL.createObjectURL(media);
    const opening = event(media, 'sourceopen', signal);
    this.video.disableRemotePlayback = true;
    this.video.src = this.url; this.video.load();
    try { await opening; } catch (error) { link.dispose(); this.restarting = false; throw error; }
    signal.throwIfAborted();
    this.video.playbackRate = continuity.rate; this.video.volume = continuity.volume;
    this.video.muted = continuity.muted; this.video.loop = continuity.loop;
    media.duration = Math.max(this.inspection.format.duration || 0, ...this.samples.tracks.map(track => track.duration));
    if (time > 0) this.video.currentTime = Math.min(time, media.duration);
    let firstResolve: () => void, firstReject: (error: unknown) => void;
    const first = new Promise<void>((resolve, reject) => { firstResolve = resolve; firstReject = reject; });
    const loaded = () => {
      if (signal.aborted) return;
      this.restarting = false;
      if (playing) void this.video.play().catch(error => {
        if (error.name !== 'NotAllowedError' && error.name !== 'AbortError' && !signal.aborted) this.options.onError?.(error);
      });
    };
    this.video.addEventListener('loadeddata', loaded, { once: true });
    const removeLoaded = () => this.video.removeEventListener('loadeddata', loaded);
    signal.addEventListener('abort', removeLoaded, { once: true });
    // Allocate every track before appending any initialization segment. Once an
    // audio-only initialization reaches HAVE_METADATA, browsers may refuse a
    // later video SourceBuffer even though both codecs are supported.
    const outputs = new Map<number, SourceBuffer>();
    for (const track of this.samples.tracks) {
      const codec = track.kind === 'video' && this.options.encoderConfig ? this.options.encoderConfig.codec : track.codec;
      const buffer = media.addSourceBuffer(`${track.kind}/mp4; codecs="${codec}"`);
      if (!(track.kind === 'video' && this.options.encoderConfig)) buffer.timestampOffset = this.samples.offset(track.id);
      outputs.set(track.id, buffer);
    }
    const copy = async (id: number) => {
      const track = this.samples.tracks.find(item => item.id === id);
      const buffer = outputs.get(id);
      await this.append(buffer, this.samples.initialization(id), signal);
      let index = this.samples.seekIndex(id, time);
      while (index < this.samples.count(id)) {
        const fragment = await this.samples.fragment(id, index, signal);
        await this.backpressure(fragment.start, signal);
        await this.trim(buffer, signal, this.samples.retentionStart(id, this.video.currentTime - MEDIA_LIMITS.bufferBehindSeconds));
        await this.append(buffer, fragment.data, signal); index = fragment.next;
        if (track.kind === 'video') firstResolve();
      }
    };
    let mux: AvcFragmentMuxer | undefined;
    const outputKeys: number[] = [];
    const transcode = async (id: number) => {
      const buffer = outputs.get(id);
      let initialized = false;
      const samples = this.samples, env = this.env;
      const encoderConfig = this.options.encoderConfig;
      this.metrics = await new BoundedVideoTranscoder(env).run({
        signal, decoderConfig: this.options.decoderConfig, encoderConfig, startTimestamp: Math.round(time * 1e6), onMetrics: this.options.onMetrics,
        chunks: async function* (signal) {
          for (let i = samples.seekIndex(id, time); i < samples.count(id); i++) {
            const packet = await samples.packet(id, i, signal);
            yield new env.EncodedVideoChunk(packet);
          }
        },
        sink: async (chunk, metadata) => {
          if (!initialized) {
            mux = new AvcFragmentMuxer(metadata.decoderConfig);
            if (metadata.decoderConfig.codec !== encoderConfig.codec) {
              if (!buffer.changeType) throw new Error('Encoder codec change requires SourceBuffer.changeType');
              buffer.changeType(`video/mp4; codecs="${metadata.decoderConfig.codec}"`);
            }
            await this.append(buffer, mux.initialization(), signal); initialized = true;
          }
          await this.backpressure(chunk.timestamp / 1e6, signal);
          if (chunk.type === 'key') outputKeys.push(chunk.timestamp / 1e6);
          const cutoff = this.video.currentTime - MEDIA_LIMITS.bufferBehindSeconds;
          while (outputKeys.length > 1 && outputKeys[1] <= cutoff) outputKeys.shift();
          await this.trim(buffer, signal, outputKeys[0] <= cutoff ? outputKeys[0] : 0);
          await this.append(buffer, mux.fragment(chunk, encoderConfig.framerate || 30), signal);
          firstResolve();
        },
      });
    };
    this.pumping = (async () => {
      const jobs = this.samples.tracks.map(track => track.kind === 'video' && this.options.encoderConfig ? transcode(track.id) : copy(track.id));
      try {
        await Promise.all(jobs); signal.throwIfAborted();
        if (media.readyState === 'open') media.endOfStream();
        firstResolve();
      } catch (error) {
        firstReject(error); link.controller.abort(error); await Promise.allSettled(jobs);
        throw error;
      } finally { mux?.close(); link.dispose(); removeLoaded(); signal.removeEventListener('abort', removeLoaded); }
    })();
    void this.pumping.catch(error => { if (!signal.aborted || signal.reason === error) {
      if (error?.name !== 'AbortError' && !this.lifetime.signal.aborted) this.options.onError?.(error);
    } });
    try { await cancellable(first, signal); }
    finally { this.restarting = false; }
  }
  private async backpressure(timestamp: number, signal: AbortSignal) {
    // A paused viewer may remain paused indefinitely; only individual waits have a deadline.
    while (timestamp > this.video.currentTime + MEDIA_LIMITS.bufferAheadSeconds) {
      await cancellable(new Promise(resolve => setTimeout(resolve, 50)), signal);
    }
  }
  private async append(buffer: SourceBuffer, bytes: ArrayBuffer, signal: AbortSignal) {
    signal.throwIfAborted();
    const operation = linkAbort(signal);
    const completed = event(buffer, 'updateend', operation.controller.signal);
    try { buffer.appendBuffer(bytes); await completed; }
    catch (error) { operation.controller.abort(); await completed.catch(() => {}); throw error; }
    finally { operation.dispose(); }
  }
  private async trim(buffer: SourceBuffer, signal: AbortSignal, before: number) {
    if (before > 0 && buffer.buffered.length && buffer.buffered.start(0) < before) {
      const operation = linkAbort(signal), completed = event(buffer, 'updateend', operation.controller.signal);
      try { buffer.remove(0, before); await completed; }
      catch (error) { operation.controller.abort(); await completed.catch(() => {}); throw error; }
      finally { operation.dispose(); }
    }
  }
  private releaseMedia() {
    if (this.url) {
      if (this.video.src === this.url) { this.video.pause(); this.video.removeAttribute('src'); this.video.load(); }
      this.env.URL.revokeObjectURL(this.url); this.url = '';
    }
    this.media = undefined;
  }
  async close() {
    this.revision++; this.lifetime.abort(); this.run?.abort(); this.video.removeEventListener('seeking', this.onSeeking);
    await this.pumping.catch(() => {}); await this.switching.catch(() => {});
    this.releaseMedia(); this.samples.close(); this.source.close(); this.inspection = undefined;
  }
}
