import { MediaCapabilityDetector } from './capability-detector';
import { MediaFormatInspector } from './format-inspector';
import { HardwareAccelerationProbe } from './hardware-acceleration-probe';
import { CodecNegotiator } from './codec-negotiator';
import { TranscodingPolicy } from './transcoding-policy';
import { RuntimePerformanceMonitor } from './runtime-performance-monitor';
import type { BoundedMediaSource, MediaEnvironment } from './types';
import type { Mp4PlaybackOptions } from './mp4-playback';

/** Shared engine for caller-provided HTTP or verified DataChannel range sources. */
export class MediaEngine {
  readonly capabilities: MediaCapabilityDetector;
  readonly inspector = new MediaFormatInspector();
  readonly negotiator = new CodecNegotiator();
  readonly policy = new TranscodingPolicy(this.negotiator);
  readonly performance = new RuntimePerformanceMonitor();
  readonly hardware: HardwareAccelerationProbe;
  constructor(private env: MediaEnvironment = globalThis) {
    this.capabilities = new MediaCapabilityDetector(env); this.hardware = new HardwareAccelerationProbe(env);
  }
  /** Explicit recovery entry: callers must first try native playback and retain their old fallback. */
  async recover(source: BoundedMediaSource, video: HTMLVideoElement, options: Mp4PlaybackOptions & { allowTranscoding?: boolean } = {}) {
    try {
      const inspection = await this.inspector.openMp4(source, options.signal);
      const { Mp4SampleStream } = await import('./mp4-sample-stream');
      const guard = new Mp4SampleStream(source, inspection); guard.close();
      const videoTrack = inspection.format.tracks.find(track => track.kind === 'video');
      const audio = inspection.format.tracks.filter(track => track.kind === 'audio');
      if (audio.some(track => this.capabilities.playback(`audio/mp4; codecs="${track.codec}"`, 'mse') !== 'supported'))
        throw new Error('Client recovery cannot preserve this audio codec');
      const samplesPlayable = this.capabilities.playback(`video/mp4; codecs="${videoTrack.codec}"`, 'mse') === 'supported';
      let decoderConfig: VideoDecoderConfig, encoderConfig: VideoEncoderConfig;
      if (!samplesPlayable) {
        if (!options.allowTranscoding) throw new Error('Client video transcoding is not enabled');
        const entry = inspection.file.getTrackById(videoTrack.id).mdia.minf.stbl.stsd.entries[0] as any;
        if ([16, 18].includes(entry.colr?.transfer_characteristics)) throw new Error('Client HDR tone mapping is unavailable');
        const ratio = Math.min(1, 1280 / videoTrack.width, 720 / videoTrack.height);
        decoderConfig = { codec: videoTrack.codec, description: videoTrack.description,
          codedWidth: videoTrack.width, codedHeight: videoTrack.height, hardwareAcceleration: 'prefer-hardware' };
        encoderConfig = { codec: 'avc1.42001f', width: Math.max(2, Math.floor(videoTrack.width * ratio / 2) * 2),
          height: Math.max(2, Math.floor(videoTrack.height * ratio / 2) * 2), framerate: 30, bitrate: 2500000,
          hardwareAcceleration: 'prefer-hardware', latencyMode: 'realtime', avc: { format: 'avc' } };
        const decode = await this.capabilities.video(decoderConfig, 'decode', options.signal);
        const encode = await this.capabilities.video(encoderConfig, 'encode', options.signal);
        const output = this.capabilities.playback(`video/mp4; codecs="${encoderConfig.codec}"`, 'mse');
        const plan = this.policy.decide({ direct: 'unsupported', path: 'mse', sourceDecode: decode.support,
          candidates: [{ codec: 'avc', codecString: encoderConfig.codec, decode: decode.support, encode: encode.support,
            playback: output, transport: output, preference: 'prefer-hardware', execution: 'unknown' }] });
        if (plan.kind !== 'client-transcode') throw new Error(`Client recovery unavailable: ${plan.reason}`);
      }
      const { Mp4StreamPlayback } = await import('./mp4-playback');
      return await Mp4StreamPlayback.open(source, inspection, video, { ...options, decoderConfig, encoderConfig }, this.env);
    } catch (error) { source.close(); throw error; }
  }
}
