import { createFile, DataStream, type Sample } from 'mp4box';
import type { MediaFormatInspector } from './format-inspector';
import { cancellable, MEDIA_LIMITS, type BoundedMediaSource, type MediaTrackInfo } from './types';

type Inspected = Awaited<ReturnType<MediaFormatInspector['openMp4']>>;
export interface MediaPacket { data: Uint8Array<ArrayBuffer>; timestamp: number; duration: number; type: 'key' | 'delta' }

/** Reuses MP4Box; rejects layouts that this incremental adapter cannot faithfully preserve. */
export class Mp4SampleStream {
  readonly tracks: MediaTrackInfo[];
  private samples = new Map<number, Sample[]>();
  private accessPoints = new Map<number, number[]>();
  private offsets = new Map<number, number>();
  private mux = createFile();
  private initializations = new Map<number, ArrayBuffer>();
  private cache?: { start: number; bytes: Uint8Array<ArrayBuffer> };
  constructor(private source: BoundedMediaSource, inspected: Inspected) {
    this.tracks = inspected.format.tracks;
    if (this.tracks.some(track => track.encrypted)) throw new Error('Encrypted media is unsupported');
    if (this.tracks.filter(track => track.kind === 'video').length !== 1 ||
      this.tracks.filter(track => track.kind === 'audio').length > 1 ||
      this.tracks.some(track => track.kind !== 'video' && track.kind !== 'audio'))
      throw new Error('Cannot preserve this media track layout');
    if (inspected.format.fragmented) throw new Error('Fragmented input requires the existing native playback path');
    for (const track of this.tracks) {
      const original = inspected.file.getTrackById(track.id), entry = original.mdia.minf.stbl.stsd.entries[0] as any;
      const matrix = original.tkhd.matrix;
      if (track.kind === 'video' && (matrix[0] !== 65536 || matrix[1] !== 0 || matrix[3] !== 0 || matrix[4] !== 65536))
        throw new Error('Cannot preserve rotated or scaled track geometry');
      const info = inspected.movie.tracks.find((item: any) => item.id === track.id);
      let empty = 0, offset = 0, edits = 0;
      for (const edit of info.edits || []) {
        if (edit.media_rate_integer !== undefined && (edit.media_rate_integer !== 1 || edit.media_rate_fraction !== 0))
          throw new Error('Cannot preserve track edit rate');
        if (edit.media_time < 0 && !edits) empty += edit.segment_duration / inspected.movie.timescale;
        else { if (++edits > 1) throw new Error('Cannot preserve multiple track edits'); offset = empty - edit.media_time / track.timescale; }
      }
      this.offsets.set(track.id, offset);
      const samples = inspected.file.getTrackSamplesInfo(track.id);
      if (!samples.length || samples.length > MEDIA_LIMITS.indexSamples) throw new Error('Media index budget exceeded');
      this.samples.set(track.id, samples);
      // Keep bounded numeric indexes. Repeated eviction must not scan a whole
      // movie's sample table on every fragment, especially for long audio tracks.
      this.accessPoints.set(track.id, samples.map((_sample, index) => index)
        .filter(index => track.kind === 'audio' || samples[index].is_sync)
        .sort((a, b) => samples[a].cts - samples[b].cts));
      this.mux.addTrack({ id: track.id, type: entry.type, timescale: track.timescale, width: track.width, height: track.height,
        hdlr: track.kind === 'audio' ? 'soun' : 'vide', channel_count: track.channels, samplerate: track.sampleRate,
        description_boxes: entry.boxes.filter((box: any) => ['avcC', 'hvcC', 'av1C', 'vpcC', 'esds', 'colr', 'pasp'].includes(box.type)) });
      this.mux.setSegmentOptions(track.id, null, { nbSamples: 16 });
    }
    this.mux.onSegment = () => {};
    for (const init of this.mux.initializeSegmentation('per-track')) this.initializations.set(init.id, init.buffer);
  }
  count(id: number) { return this.samples.get(id)?.length || 0; }
  offset(id: number) { return this.offsets.get(id) || 0; }
  initialization(id: number) { return this.initializations.get(id); }
  seekIndex(id: number, seconds: number) {
    const track = this.tracks.find(item => item.id === id), samples = this.samples.get(id);
    const target = (seconds - this.offset(id)) * track.timescale;
    const points = this.accessPoints.get(id);
    let low = 0, high = points.length;
    while (low < high) {
      const middle = Math.floor((low + high) / 2);
      if (samples[points[middle]].cts <= target) low = middle + 1;
      else high = middle;
    }
    return low ? points[low - 1] : 0;
  }
  /** MSE remove() also removes dependent frames until the next keyframe.
   * End removal exactly at a retained random access point, never mid-GOP. */
  retentionStart(id: number, seconds: number) {
    const sample = this.samples.get(id)?.[this.seekIndex(id, seconds)];
    const track = this.tracks.find(item => item.id === id);
    return sample ? sample.cts / track.timescale + this.offset(id) : 0;
  }
  async packet(id: number, index: number, signal?: AbortSignal): Promise<MediaPacket> {
    const sample = this.samples.get(id)?.[index], track = this.tracks.find(item => item.id === id);
    if (!sample || !Number.isSafeInteger(sample.offset) || sample.offset < 0 || sample.size <= 0 || sample.size > MEDIA_LIMITS.readBytes)
      throw new Error('Media sample budget exceeded');
    const end = sample.offset + sample.size;
    if (!this.cache || sample.offset < this.cache.start || end > this.cache.start + this.cache.bytes.byteLength) {
      const readEnd = Math.min(this.source.size ?? end, sample.offset + MEDIA_LIMITS.readBytes);
      this.cache = { start: sample.offset, bytes: await cancellable(this.source.read(sample.offset, readEnd, signal), signal) };
    }
    if (end > this.cache.start + this.cache.bytes.byteLength) throw new Error('Truncated media sample');
    return { data: this.cache.bytes.subarray(sample.offset - this.cache.start, end - this.cache.start),
      timestamp: Math.round((sample.cts / track.timescale + this.offset(id)) * 1e6),
      duration: Math.round(sample.duration / track.timescale * 1e6), type: sample.is_sync ? 'key' : 'delta' };
  }
  async fragment(id: number, index: number, signal?: AbortSignal) {
    const original = this.samples.get(id), track = this.tracks.find(item => item.id === id);
    const first = original[index], samples: Sample[] = [];
    let bytes = 0;
    while (index < original.length && samples.length < 16) {
      const sample = original[index];
      if (samples.length && (sample.dts - first.dts > track.timescale * .25 || bytes + sample.size > MEDIA_LIMITS.encodedBytes)) break;
      const packet = await this.packet(id, index++, signal);
      samples.push({ ...sample, data: packet.data }); bytes += sample.size;
    }
    return { data: mp4Fragment(this.mux, samples), next: index,
      start: first.cts / track.timescale + this.offset(id),
      end: Math.max(...samples.map(sample => (sample.cts + sample.duration) / track.timescale + this.offset(id))) };
  }
  close() { this.cache = undefined; this.samples.clear(); this.accessPoints.clear(); this.initializations.clear(); this.mux.stop(); }
}

export function mp4Fragment(file: ReturnType<typeof createFile>, samples: Sample[]) {
  const moof = file.createMoof(samples), stream = new DataStream();
  moof.write(stream);
  stream.adjustUint32(moof.trafs[0].truns[0].data_offset_position, moof.size + 8);
  const size = samples.reduce((sum, sample) => sum + sample.data.byteLength, 0);
  if (size > MEDIA_LIMITS.encodedBytes) throw new Error('Media fragment budget exceeded');
  stream.writeUint32(size + 8); stream.writeString('mdat');
  const header = new Uint8Array(stream.buffer), data = new Uint8Array(header.byteLength + size);
  data.set(header); let offset = header.byteLength;
  for (const sample of samples) { data.set(sample.data, offset); offset += sample.data.byteLength; }
  return data.buffer;
}

/** H.264 fMP4 output; other encoder outputs require a separately validated mux path. */
export class AvcFragmentMuxer {
  private file = createFile();
  private id: number;
  private count = 0;
  constructor(configuration: VideoDecoderConfig) {
    if (!configuration.codec.startsWith('avc1') || !configuration.description) throw new Error('AVC decoder configuration required for MP4');
    const description = ArrayBuffer.isView(configuration.description)
      ? new Uint8Array(configuration.description.buffer, configuration.description.byteOffset, configuration.description.byteLength)
      : new Uint8Array(configuration.description);
    this.id = this.file.addTrack({ type: 'avc1', timescale: 1000000, width: configuration.codedWidth, height: configuration.codedHeight,
      avcDecoderConfigRecord: description.slice().buffer });
    this.file.setSegmentOptions(this.id, null, { nbSamples: 1 }); this.file.onSegment = () => {};
  }
  initialization() { return this.file.initializeSegmentation('per-track')[0].buffer; }
  fragment(chunk: EncodedVideoChunk, fps: number) {
    const data = new Uint8Array(chunk.byteLength); chunk.copyTo(data);
    const duration = Math.max(chunk.duration || 0, Math.round(1e6 / fps));
    return mp4Fragment(this.file, [{ track_id: this.id, number: this.count++, description_index: 1,
      dts: chunk.timestamp, cts: chunk.timestamp, duration, is_sync: chunk.type === 'key', data, size: data.byteLength } as Sample]);
  }
  close() { this.file.stop(); }
}
